 final ExecutorService downloads=Executors.newSingleThreadExecutor();final ConcurrentHashMap<String,Long> downloadTickets=new ConcurrentHashMap<>();final Set<String> downloading=ConcurrentHashMap.newKeySet(),waitingDownloads=ConcurrentHashMap.newKeySet(),cancelledDownloads=ConcurrentHashMap.newKeySet();
