  @JavascriptInterface public void driveDisconnect(){runOnUiThread(()->{drive.disconnect();try{if(AudioService.active)startService(new Intent(MainActivity.this,AudioService.class).setAction("disconnectDrive"));}catch(Exception ignored){}records.entrySet().removeIf(e->"drive".equals(e.getValue().optString("storage")));});}
  @JavascriptInterface public void importAudio(String kind){tell("На телефоне доступна только библиотека Google Диска");}
  @JavascriptInterface public void playQueue(String ids,String current,boolean shuffle,String repeat,String kind){runOnUiThread(()->{try{JSONArray wanted=new JSONArray(ids),items=new JSONArray();boolean needsDrive=false;for(int i=0;i<Math.min(wanted.length(),2000);i++){JSONObject b=book(wanted.optString(i));if(b==null||!FolderAccess.ROOT.equals(b.optString("allowedRoot")))continue;NativeProgress.get(MainActivity.this).register(b);if("drive".equals(b.optString("storage")))needsDrive=true;JSONObject item=new JSONObject();for(String field:Arrays.asList("id","fileId","uri","title","name","artist","author","cover","storage","catalogPath","series","downloadOf","allowedRoot","accountId"))if(b.has(field))item.put(field,b.get(field));item.put("kind","book".equals(kind)?"book":"music");items.put(item);}final JSONArray selected=items;if(needsDrive){if(!drive.connected()){tell("Подключите Google Диск");return;}drive.withToken((token,generation)->{if(generation==drive.generation)startQueue(selected,current,shuffle,repeat,token);},true);}else startQueue(selected,current,shuffle,repeat,"");}catch(Exception e){tell("Не удалось открыть очередь");}});}
  @JavascriptInterface public void driveCollections(){runOnUiThread(()->drive.collections(items->js("onCollections",items)));}
  @JavascriptInterface public void play(String id){runOnUiThread(()->{JSONObject b=book(id);if(b==null||!FolderAccess.ROOT.equals(b.optString("allowedRoot"))){tell("Обновите библиотеку");return;}NativeProgress.get(MainActivity.this).register(b);if("drive".equals(b.optString("storage"))){if(!drive.connected()){tell("Подключите Google Диск");return;}drive.withToken((token,generation)->{if(generation==drive.generation)startAudio(b,"https://www.googleapis.com/drive/v3/files/"+b.optString("fileId")+"?alt=media",token);},true);}else startAudio(b,b.optString("uri"),"");});}
  @JavascriptInterface public void download(String id,String kind){runOnUiThread(()->{JSONObject b=book(id);if(b==null||!"drive".equals(b.optString("storage"))){tell("Выберите запись Google Диска");return;}if(!drive.connected()){tell("Подключите Google Диск");return;}if(drive.authorizing){downloadState(id,"error",0,-1,"Дождитесь завершения входа Google и повторите загрузку.","");return;}if(!downloading.add(id))return;cancelledDownloads.remove(id);waitingDownloads.add(id);final long ticket=System.nanoTime();downloadTickets.put(id,ticket);downloadState(id,"waiting",0,-1,"","");drive.withToken((token,generation)->{waitingDownloads.remove(id);if(!Long.valueOf(ticket).equals(downloadTickets.get(id)))return;downloads.execute(()->downloadAudio(b,kind,token,generation,ticket));},true);});}
  @JavascriptInterface public void cancelDownload(String id){cancelledDownloads.add(id);downloadTickets.remove(id);waitingDownloads.remove(id);downloading.remove(id);downloadState(id,"cancelled",0,-1,"","");}
  @JavascriptInterface public void completion(String id,boolean complete){NativeProgress.get(MainActivity.this).completion(id,complete);java.util.Set<String> ids=new HashSet<>(getSharedPreferences("progress",0).getStringSet("completedIds",Collections.emptySet()));if(complete)ids.add(id);else ids.remove(id);getSharedPreferences("progress",0).edit().putStringSet("completedIds",ids).apply();}
  @JavascriptInterface public void configure(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,30);}catch(Exception e){tell("Не удалось открыть выбор конфига");}});}
